/// <summary>
/// Vendor account is required for vendor rebates with Invoice consolidation by rebate type = Yes
/// </summary>
/// <returns>True if validation successful; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (ret)
    {            
        if (this.ModuleInventCustVend == ModuleInventCustVend::Vend && !this.METVendAccount)                
        {
            ret = checkFailed(strFmt("@RebatesAndDeductions:FieldMustBeSpecified", fieldPName(TAMRebateDeal, METVendAccount)));
        }
    }

    return ret;
}

/// <summary>
/// CB705_VendorRebatePosting
/// Add rebate posting profiles where DynamicAccount is METPurchasedFromVendor in the lookup
/// </summary>
/// <param name = "_rebateDeal"><c>TAMRebateDeal</c> record</param>
/// <param name = "_formControl">Form control</param>
/// <returns><c>Query</c> for the posting profile lookup</returns>
public static Query buildLookupPostingProfileQuery(TAMRebateDeal _rebateDeal, FormControl _formControl)
{
    Query query = next buildLookupPostingProfileQuery(_rebateDeal, _formControl);

    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(TAMRebatePosting));

    // Add rebate posting profiles where DynamicAccount is METPurchasedFromVendor in the lookup
    if (TAMRebateParameters::find().METProcessVendRebateBasedVendRebType
    &&  _formControl && _formControl.dataSourceObject() 
    &&  _formControl.dataSourceObject().table() == tableNum(TAMRebateDeal))
    {
        qbds.addRange(fieldNum(TAMRebatePosting, DynamicAccount)).value(queryValue(TAMRebateDynamicAccount::METPurchasedFromVendor));
    }
    return query;
}

/// <summary>
/// CB705_VendorRebatePosting
/// When module is changed from Vendor, clear METVendAccount and METInvoiceConsolidationByRebateType
/// </summary>
/// <param name = "_fieldName">Field name</param>
/// <param name = "_arrayIndex">Array index</param>
public void modifiedFieldValue(FieldName _fieldName, int _arrayIndex)
{
    next modifiedFieldValue(_fieldName, _arrayIndex);

    switch (_fieldName)
    {
        case fieldStr(TAMRebateDeal, ModuleInventCustVend) :
            if (this.ModuleInventCustVend == ModuleInventCustVend::Cust)
            {                    
                this.METVendAccount = METConstants::emptyString;
                this.METInvoiceConsolidationByRebateType = NoYes::No;
            }

            break;              
    }
}
